style.css:
@-moz-document domain("classroom.google.com") {
/* Very Direct Body Styling */
  body {
    background: linear-gradient(to bottom, #222, #000) !important;
    color: #eee !important;
  }

  /* Header - Target by role and aria-label */
  header[role="banner"] {
    background: rgba(0, 0, 0, 0.7) !important;
    border-bottom: 1px solid #333 !important;
  }

  header[role="banner"] [aria-label="Google Classroom"] {
    color: #00bfff !important;
    text-shadow: 1px 1px 2px #000 !important;
  }

  /* Main Content Area - Targeting the Main Container */
  div[jscontroller="jofVaa"] > div > div:nth-child(2) { /* Targeting the main content div */
    padding: 20px !important;
  }

  /* Assignment Cards - Targeting List Items */
  div[jscontroller="jofVaa"] > div > div:nth-child(2) div[role="listitem"] {
    background: rgba(30, 30, 30, 0.8) !important;
    border: 1px solid #444 !important;
    border-radius: 8px !important;
    padding: 20px !important;
    margin-bottom: 20px !important;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5) !important;
    transition: transform 0.3s !important;
  }

  div[jscontroller="jofVaa"] > div > div:nth-child(2) div[role="listitem"]:hover {
    transform: translateY(-5px) !important;
  }

  /* Assignment Titles */
  div[jscontroller="jofVaa"] > div > div:nth-child(2) div[role="listitem"] div[role="heading"] {
    color: #00bfff !important;
    margin-bottom: 10px !important;
  }

  /* Assignment Descriptions */
  div[jscontroller="jofVaa"] > div > div:nth-child(2) div[role="listitem"] div[jsname="z80M1"] {
    line-height: 1.6 !important;
  }

  /* Buttons */
  button.uArJ5e.UQuaGc.Y5sE8d.bxPAYd.kF10vd.L4o7Ab.cr27je {
    background-color: #007bff !important;
    color: #fff !important;
    padding: 10px 20px !important;
    border: none !important;
    border-radius: 5px !important;
    cursor: pointer !important;
    transition: background-color 0.3s !important;
  }

  button.uArJ5e.UQuaGc.Y5sE8d.bxPAYd.kF10vd.L4o7Ab.cr27je:hover {
    background-color: #0056b3 !important;
  }

  /* Footer */
  footer[role="contentinfo"] {
    background: rgba(0, 0, 0, 0.7) !important;
    padding: 15px !important;
    text-align: center !important;
    border-top: 1px solid #333 !important;
    color: #888 !important;
  }
}
